# Check what's in kernel state
print(f"Grid shape: {len(grid)}x{len(grid[0])}")
print(f"Total 1s in grid: {sum(sum(row) for row in grid)}")

# Re-run proper component finding using helper if available
if 'find_connected_components' in globals():
    comps = find_connected_components(grid, start=(0,0))
    print(f"\nFound {len(comps)} components via find_connected_components")
else:
    # Manual 4-way connected components for 1s
    visited = set()
    comps = []

    def get_comp(sr, sc):
        if (sr,sc) in visited or not (0<=sr<len(grid) and 0<=sc<len(grid[0])) or grid[sr][sc]!=1:
            return None
        visited.add((sr,sc))
        region = {(sr,sc)}
        q = [(sr,sc)]
        while q:
            r,c = q.pop(0)
            for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr,nc = r+dr, c+dc
                if 0<=nr<len(grid) and 0<=nc<len(grid[0]) and grid[nr][nc]==1 and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    region.add((nr,nc))
                    q.append((nr,nc))
        return region

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c]==1 and (r,c) not in visited:
                comp = get_comp(r,c)
                if comp:
                    comps.append(comp)

    print(f"Found {len(comps)} components of value 1")
    sizes = sorted([len(c) for c in comps], reverse=True)
    print(f"Sizes: {sizes[:10]}...")

# Submit both filled rectangular frames
def create_filled_rect(r_min, c_min, r_max, c_max):
    """Create a filled rectangle grid with 0s and 1s."""
    rows, cols = len(grid), len(grid[0])
    result = [[0]*cols for _ in range(rows)]
    for r in range(r_min, r_max+1):
        for c in range(c_min, c_max+1):
            result[r][c] = 1
    return result

# Frame 1: 7x7 at [4,5,10,11], size=24 -> filled = 49 cells
frame1_filled = create_filled_rect(4, 5, 10, 11)
print(f"Frame 1 filled: {sum(sum(row) for row in frame1_filled)} cells")

